public void writeDimensionsIntoRow(final ResultRow resultRow, final GroupByQuery query, final Iterator<Object> results)
{
  final List<DimensionSpec> dims = query.getDimensions();
  final int dimensionStart = query.getResultRowDimensionStart();
  for (int dimPos = 0; dimPos < dims.size(); dimPos++) {
    if (!results.hasNext()) {
      throw new ISE("Ran out of objects while reading dimensions from cache at position[%s]", dimPos);
    }
    resultRow.set(dimensionStart + dimPos, convertCacheDimensionValue(results.next(), dims.get(dimPos)));
  }
}

public void writePostAggregatorsIntoRow(final ResultRow resultRow, final GroupByQuery query, final Iterator<Object> results)
{
  final int postAggregatorStart = query.getResultRowPostAggregatorStart();
  final int postAggregatorCount = countPostAggregators(query);
  for (int postPos = 0; postPos < postAggregatorCount; postPos++) {
    if (!results.hasNext()) {
      throw new ISE("Ran out of objects while reading post aggregators from cache at position[%s]", postPos);
    }
    resultRow.set(postAggregatorStart + postPos, results.next());
  }
}

public ResultRow createRowFromCacheParts(
    final GroupByQuery query,
    final boolean isResultLevelCache,
    final DateTime timestamp,
    final Iterator<Object> results
)
{
  final int size = isResultLevelCache
                   ? query.getResultRowSizeWithPostAggregators()
                   : query.getResultRowSizeWithoutPostAggregators();
  final ResultRow resultRow = ResultRow.create(size);
  if (query.getResultRowHasTimestamp()) {
    resultRow.set(0, timestamp.getMillis());
  }
  writeDimensionsIntoRow(resultRow, query, results);
  return resultRow;
}

